import{z as s,x as i,o as r,c as d,q as n,j as A,D as B,d as E,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"B+ 树的并发控制","description":"","frontmatter":{"title":"B+ 树的并发控制","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dbk-btree-concurrency.md","filePath":"cs/dbk-btree-concurrency.md","lastUpdated":1791413859000}'),p={name:"cs/dbk-btree-concurrency.md"};function c(C,a,h,D,F,b){const t=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="b-树的并发控制" tabindex="-1">B+ 树的并发控制 <a class="header-anchor" href="#b-树的并发控制" aria-label="Permalink to &quot;B+ 树的并发控制&quot;">​</a></h1><div class="epigraph"><p>读者可以走一棵正在被改写的树，条件是作者每次只动一页，并且先把新页挂到读者看得见的地方。</p><footer>—— 据 Lehman and Yao, ACM TODS, 1981；Mohan, ARIES/IM, SIGMOD 1990 整理</footer></div><p><a href="/cs/dbk-pages-bufferpool">上一课</a>把缓冲池立成契约：fix 页、持 pin、不许持闩做 I/O。缺口立刻出现：索引不是一页，是一棵树；一次探测要串起好几页，一次插入还可能改结构。主干 <a href="/cs/latch-crabbing">latch crabbing</a> 已给了读协议（逐层蟹行、读最多同持两层）与 B-link 的乐观读法；本课写实现侧剩下的硬骨头——结构变更（分裂、合并）期间闩按什么序拿、按什么序放，读者怎么发现「叶页在我脚下换了」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>蟹行协议在「只改一行、不改结构」时够用；插入一旦触发<a href="/cs/bplus-split">分裂</a>，实现必须回答三个次序问题：新叶页先挂右链还是先挂父指针？父页的闩何时拿、持有到何时？读者正在探测的页恰在此时分裂，它凭什么知道自己看到的不是全部？次序错了会错在哪：先挂父指针、后写右链，读者从左叶就可能永久跳过新页右半的键——丢的不是一行，而是整个键区间；祖先闩放得过早，两个并发插入各自分裂同一父页，父页出现重复分隔键，树的可搜索性就此破坏。</p><p><span class="marginnote">「闩」（latch）翻译过来是保护内存页几微秒的短把手，像厕所门插销，出来就开；「锁」（lock）保护一行数据直到事务提交，像把房间租下一整个租期。把两者混用——比如持闩等到提交——正是索引实现里最典型的翻车点。</span></p><h3 id="一次分裂的次序" tabindex="-1">一次分裂的次序 <a class="header-anchor" href="#一次分裂的次序" aria-label="Permalink to &quot;一次分裂的次序&quot;">​</a></h3><p>自底向上记这个序列：定位叶页并持写闩，同时按「安全节点」规则决定要不要留着祖先闩——叶页不满则此次插入绝不分裂，祖先闩立刻可放；真要分裂时，先分配右页、搬走半数记录、写右页的右链指向左页原右邻——此刻右页已对沿右链走的读者可见——最后回到父页插入分隔键，父指针生效。实现从这条次序里得到两条纪律：闩只从根向下、只向右邻拿，绝不向上，全序无环，死锁在树闩层天然不可能，<a href="/cs/db-deadlock">库内死锁</a>那套等待图在这一层用不上；持闩集合有上界——一次写路径至多树高个页闩加 pin，而「不许持闩做 I/O」（上一课）防的正是这个局面：你要的下一页若成了牺牲者，两边互相等待。</p><p><span class="marginnote">量级感：扇出几百的 B+ 树，根到叶只要三四层。树高既是 I/O 账，也是闩账——一次探测至多同持几个页闩，高扇出直接压低全引擎的闩流量；而根页写闩正是全局串行点，热点插入的竞争全在这一个字节上排队。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现把次序写成三个函数的分工。探测：根到叶逐层取读闩、蟹行；到叶后若目标键大于本叶上界，放闩、闩右邻重试——右链就是为「脚下换页」准备的恢复路径。插入：自上而下持闩，遇到安全节点就释放其全部祖先闩，把持闩集合从树高收缩到一小段；确认要分裂时才把父闩攥在手里。结构变更按上面记的次序：先右链、后父指针。B-link 树把协议再放宽一档：读全程不闩内节点，只闩叶；发现页被分裂就沿右链走，用重试换掉父闩——读更便宜，代价是探测可能多走几步。InnoDB 则用树级 SX 意向闩：可能改结构的插入持 SX（与写互斥、与读相容），纯读不碰树闩，根页的写闩不再卡全局。</p>',11)),(r(),A(o,null,{default:B(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E6%8F%92%E5%85%A5%20k%22%5D%20--%3E%20CRAB%5B%22%E8%87%AA%E4%B8%8A%E8%80%8C%E4%B8%8B%E6%8C%81%E9%97%A9%E5%88%B0%E5%8F%B6%22%5D%0A%20%20CRAB%20--%3E%20SAFE%7B%22%E5%8F%B6%E4%BC%9A%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20SAFE%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E9%87%8A%E6%94%BE%E7%A5%96%E5%85%88%E9%97%A9%22%5D%0A%20%20SAFE%20--%3E%7C%E6%98%AF%7C%20HOLD%5B%22%E4%BF%9D%E7%95%99%E7%88%B6%E9%97%A9%22%5D%0A%20%20DROP%20--%3E%20INS%5B%22%E6%8F%92%E5%85%A5%E8%AE%B0%E5%BD%95%22%5D%0A%20%20HOLD%20--%3E%20SPLIT%5B%22%E5%88%86%E8%A3%82%EF%BC%9A%E5%88%86%E9%85%8D%E5%8F%B3%E9%A1%B5%EF%BC%8C%E5%85%88%E6%8C%82%E5%8F%B3%E9%93%BE%22%5D%0A%20%20SPLIT%20--%3E%20PAR%5B%22%E7%88%B6%E9%A1%B5%E6%8F%92%E5%85%A5%E5%88%86%E9%9A%94%E9%94%AE%22%5D%0A%20%20INS%20--%3E%20DONE%5B%22%E9%87%8A%E6%94%BE%E5%85%A8%E9%83%A8%E9%97%A9%22%5D%0A%20%20PAR%20--%3E%20DONE%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("为什么读者永远不需要闩父页：因为树的可达性只在父指针生效那一刻增加，而右链保证父指针生效前后，任何键都至少有一条从根或从左邻可达的路径。读者要的不是「树不变」，而是「我看到的每个指针都通向覆盖目标键区间的某个页」——右链把这个不变量从「结构不变」弱化成「区间覆盖不变」，写者就自由了。并发控制因此分两层：树闩保护页与指针的形状，事务锁（"),e("a",{href:"/cs/two-pl"},"两阶段锁"),E("的语义，实现是第 5 课）保护键区间的逻辑内容。把两层混成一层的典型事故：把幻读防护塞进树闩，纯读开始互相阻塞；把页闩持有到提交，闩就得像锁一样做死锁检测。")],-1)),a[5]||(a[5]=e("p",null,"读者发现「叶页在我脚下换了」之后的恢复路径：",-1)),(r(),A(o,null,{default:B(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%BB%E8%80%85%E9%97%A9%E4%BD%8F%E5%BD%93%E5%89%8D%E5%8F%B6%E9%A1%B5%22%5D%20--%3E%20C%7B%22%E7%9B%AE%E6%A0%87%E9%94%AE%E5%A4%A7%E4%BA%8E%E6%9C%AC%E5%8F%B6%E4%B8%8A%E7%95%8C%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E5%B0%B1%E5%9C%A8%E6%9C%AC%E9%A1%B5%22%7C%20F%5B%22%E5%8F%96%E8%AE%B0%E5%BD%95%EF%BC%9A%E6%8E%A2%E6%B5%8B%E5%AE%8C%E6%88%90%22%5D%0A%20%20C%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E6%9C%AC%E9%A1%B5%E5%8F%AF%E8%83%BD%E5%B7%B2%E8%A2%AB%E5%88%86%E8%A3%82%22%7C%20RL%5B%22%E6%94%BE%E9%97%A9%EF%BC%8C%E6%B2%BF%E5%8F%B3%E9%93%BE%E8%B5%B0%E5%88%B0%E5%8F%B3%E9%82%BB%22%5D%0A%20%20RL%20--%3E%20RE%5B%22%E9%97%A9%E4%BD%8F%E5%8F%B3%E9%82%BB%E9%A1%B5%E9%87%8D%E6%96%B0%E6%9F%A5%22%5D%0A%20%20RE%20--%3E%20F%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字感受 B-link 的账：树高 4 层时，普通读要同持 4 个读闩；B-link 读全程只闩叶页 1 个，偶尔回退多走一页右链。写入高峰期，省掉的三层闩竞争，往往比多走的那一步更值钱——用重试换并发度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写闩协议，不写闩本身（每闩一个原字节的 CAS 状态机即可）；合并与分裂对称但多一个「父页可能欠载」的级联，主干已有，不重讲。Bw-tree 用映射表加增量记录把写闩整个去掉，主干 Bw-tree 一课对照过，本课程不实现。多核下 SX 仍不够热时，要版本化读或子树独立闩，那是性能工程，不改变正确性协议。</p><p><span class="marginnote">初学者容易以为「树闩层无死锁」等于索引并发万无一失。死锁不可能只因闩守了全序（向下、向右）；幻读、丢失更新这些逻辑问题仍由事务锁管。树闩层永远不用等待图，锁层照样要做死锁检测——两层各管各的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分裂次序：先右链后父指针，可达性只在父指针生效时增加。</li><li>闩全序（向下、向右）使死锁在树闩层不可能；持闩集合以树高为上界。</li><li>右链把不变量从「结构不变」弱化为「区间覆盖不变」，读者用重试换掉父闩。</li><li>树闩管形状，事务锁管内容；混层是头号实现事故。</li><li>出处：Lehman and Yao, TODS 1981；Mohan, ARIES/IM, SIGMOD 1990；Gray and Reuter, 1993。</li></ul>',6))])}const f=s(p,[["render",c]]);export{u as __pageData,f as default};
